$templateCache.put('app/Submodules/EntityTasks/entityTasks.directive.html','<div class="dropdown-menu-card-tasks">\n  <div uib-dropdown>\n    <a class="deal-task-click" id="task_list" href ng-click="entityTasksCtrl.getObjectTasks()" uib-dropdown-toggle>\n      <i ng-class="{\'text-warning\': entityTasksCtrl.next_task === \'today\', \'text-danger\': entityTasksCtrl.next_task === \'late\', \'text-muted\': entityTasksCtrl.next_task === \'future\' || !entityTasksCtrl.next_task || entityTasksCtrl.next_task === \'\', \'fal fa-calendar-exclamation\': entityTasksCtrl.next_task, \'fal fa-calendar\': !entityTasksCtrl.next_task || entityTasksCtrl.next_task === \'\' }" class="font-big" aria-label="{{ \'ARIA_LABELS.DEAL.CARD_TASK_ICON\' | translate }}"></i>\n    </a>\n    <ul aria-labelledby="tasks" class="white-dropdown-menu pull-right no-padding-top width-230 tasks-ul" uib-dropdown-menu>\n      <div class="dropdown-subtitle">\n        {{ \'ENTITY_TASKS.PENDING_TASKS\' | translate }}\n      </div>\n      <div class="task-dropdown">\n        <li class="wrapper text-neutral font-semi-big text-center" ng-if="!entityTasksCtrl.initial_load">\n          <div class="loader table-loader"></div>\n        </li>\n        <li ng-if="entityTasksCtrl.initial_load && entityTasksCtrl.tasks.length === 0" class="wrapper text-muted font-semi-big text-center">\n          {{ \'ENTITY_TASKS.NO_TASKS_FOUND\' | translate }}\n        </li>\n        <li ng-if="entityTasksCtrl.initial_load && entityTasksCtrl.tasks.length > 0" ng-repeat="task in entityTasksCtrl.tasks" class="short-wrapper b-b-1 white-content">\n          <div class="white-dropdown-link">\n            <div class="hbox fixed-size">\n              <aside class="width-45" ng-if="task.Editable">\n                <div class="round-checkbox" ng-click="entityTasksCtrl.toggleFinishTask(task); $event.stopPropagation()">\n                  <div class="b-2" ng-if="!task.loadingIcon" uib-tooltip="Finalizar tarefa" tooltip-append-to-body="true">\n                    <i class="fas fa-check activity-icon"></i>\n                  </div>\n                  <div class="loader modal-loader task-list-loader" style="width: 27px; height: 27px; margin: 0" ng-if="task.loadingIcon"></div>\n                </div>\n              </aside>\n              <aside>\n                <span class="font-bold">{{task.Title || task.Type.Name}}</span>\n                <div class="overflow-hidden nowrap ellipsis" ng-show="task.Description.length > 0">\n                  {{task.Description}}\n                </div>\n                <div class="mtop5"><span class="timeline-clock">\n                  <div><i class="fal fa-clock"> </i> {{task.formatted_date}}</div></span></div>\n                  <div class="gap-5"></div>\n                  <div class="big-simple-inline text-muted font-big">\n                    <span class="inline-link-muted">\n                      <a class="font-small" ui-sref="{{state.current.name + \'.task({id: task.Id})\'}}">\n                        {{ \'ENTITY_TASKS.VISUALIZE\' | translate }}\n                      </a>\n                    </span>\n                  </div>\n                </aside>\n              </div>\n            </div>\n          </li>\n        </div>\n        <div class="white-content b-t-1"></div>\n        <span ng-if="entityTasksCtrl.has_permission_to_create_task" class="button no-border button-square button-full-width button-big button-white text-left" ui-sref="{{state.current.name + \'.newtask({contact: entityTasksCtrl.contact, deal: entityTasksCtrl.deal})\'}}">\n          <strong class="font-regular-size">\n            <span class="text-action"><i class="fal fa-calendar-plus simple-line-space"></i></span>\n            {{ \'ENTITY_TASKS.NEW_TASK\' | translate }}\n          </strong>\n        </span>\n        <div class="white-content b-t-1"></div>\n        <span class="button no-border button-square button-full-width button-big button-white text-left" ui-sref="{{state.current.name + \'.newinteractionrecord({contact: entityTasksCtrl.contact, deal: entityTasksCtrl.deal})\'}}">\n          <span class="text-action"><i class="fal fa-comment-plus simple-line-space"></i></span>\n          <strong class="font-regular-size">\n            {{ \'ENTITY_TASKS.NEW_INTERACTION_RECORD\' | translate }}\n          </strong>\n        </span>\n      </ul>\n    </div>\n  </div>\n');
